int webgal_plan_add_audio(WebgalPlan* plan, uint64_t start_us, uint64_t end_us, int has_end,
                          const char* path, int kind, float volume, int loop, uint32_t fade_in_ms,
                          uint32_t fade_out_ms) {
    if (plan == nullptr || !valid_string(path)) {
        return WEBGAL_STATUS_INVALID_ARGUMENT;
    }
    try {
        webgal::job::AudioEvent event;
        event.start_us = start_us;
        if (has_end != 0) {
            event.end_us = end_us;
        }
        event.path = path;
        switch (kind) {
        case WEBGAL_AUDIO_VOCAL:
            event.kind = webgal::job::AudioKind::Vocal;
            break;
        case WEBGAL_AUDIO_EFFECT:
            event.kind = webgal::job::AudioKind::Effect;
            break;
        default:
            event.kind = webgal::job::AudioKind::Bgm;
            break;
        }
        event.volume = clamp_finite(volume, 0.0F, 1.0F, 1.0F);
        event.loop = loop != 0;
        event.fade_in_ms = fade_in_ms;
        event.fade_out_ms = fade_out_ms;
        plan->plan.audio.push_back(std::move(event));
        return WEBGAL_STATUS_OK;
    } catch (...) {
        return WEBGAL_STATUS_INVALID_ARGUMENT;
    }
}

int webgal_render_run(const WebgalPlan* plan, const WebgalRenderOptions* options,
                      const WebgalRenderCallbacks* callbacks, char* error_buffer,
                      size_t error_buffer_len) {
    if (error_buffer != nullptr && error_buffer_len > 0) {
        error_buffer[0] = '\0';
    }
    if (plan == nullptr || options == nullptr) {
        write_error(error_buffer, error_buffer_len, "缺少计划或导出参数");
        return WEBGAL_STATUS_INVALID_ARGUMENT;
    }
    try {
        std::string error;
        const Status status = run_render(*plan, *options, callbacks, error);
        if (status != WEBGAL_STATUS_OK) {
            write_error(error_buffer, error_buffer_len, error.empty() ? "导出失败" : error);
        }
        return status;
    } catch (const std::exception& exception) {
        write_error(error_buffer, error_buffer_len, std::string("渲染器异常: ") + exception.what());
        return WEBGAL_STATUS_RENDER_FAILED;
    } catch (...) {
        write_error(error_buffer, error_buffer_len, "渲染器抛出未知异常");
        return WEBGAL_STATUS_RENDER_FAILED;
    }
}

